#include <stdint.h>
#define NAME_LEN 10

struct sensor_frame {
    uint8_t  id;
    uint32_t timestamp;
    uint16_t temperature;
    uint8_t  flags;
    double   pressure;
    char     name[NAME_LEN];
    uint16_t crc;
};

input.code:
typedef struct {
    uint16_t x, y;
} point_t;

typedef struct __attribute__((packed)) {
    uint8_t  version : 4;
    uint8_t  type    : 4;
    uint16_t length;
    uint32_t seq;
    point_t  origin;
    uint8_t  payload[16];
} msg_header_t;
